import { useMemo, useState } from 'react'; import { useAppState } from '../../app/AppState'; import { Badge, Button, Card, CardHeader, Textarea } from '../../components/ui';
const prompts = {
  Script: `# MODE B EXTERNAL AUTHORING — SCRIPT\n\nCreate a structured demo script for project VB-0024.\nPreserve section IDs and return one UTF-8 JSON object only.\nDEMO: no reservation, schema acceptance or backend task exists.`,
  Storyboard: `# MODE B EXTERNAL AUTHORING — STORYBOARD\n\nCreate shot briefs for project VB-0024 using the selected B2 Colorful contract.\nPreserve scene and shot IDs and return one UTF-8 JSON object only.\nDEMO: no image provider or production import is connected.`,
  Captions: `# MODE B EXTERNAL AUTHORING — CAPTIONS\n\nCreate concise portrait-safe caption cues for project VB-0024.\nPreserve cue ordering and return one UTF-8 JSON object only.\nDEMO: no audio alignment or production import is connected.`
} as const;
type PromptTab = keyof typeof prompts;
export function ExternalWorkspace() { const [tab, setTab] = useState<PromptTab>('Script'); const [json, setJson] = useState(''); const [result, setResult] = useState<'idle'|'valid'|'invalid'>('idle'); const { showNotice } = useAppState(); const activePrompt=useMemo(()=>prompts[tab],[tab]); const validate = () => { try { const parsed: unknown = JSON.parse(json); setResult(parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed) ? 'valid' : 'invalid'); } catch { setResult('invalid'); } }; const copyPrompt=()=>navigator.clipboard.writeText(activePrompt).then(()=>showNotice(`${tab} demo prompt copied.`)).catch(()=>showNotice('Clipboard unavailable.')); const exportPrompt=()=>{const blob=new Blob([activePrompt],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`mode-b-${tab.toLowerCase()}-demo.md`;anchor.click();window.setTimeout(()=>URL.revokeObjectURL(url),0);showNotice(`${tab} demo prompt exported.`)}; return <div className="grid wide-left"><Card><CardHeader title="External task prompt" hint="Copy to ChatGPT manually · no embedded API" action={<Badge tone="amber">DEMO</Badge>} /><div className="tabs">{(Object.keys(prompts) as PromptTab[]).map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div><pre className="prompt" data-active-prompt={tab}>{activePrompt}</pre><div className="actions"><Button variant="primary" onClick={copyPrompt}>Copy prompt</Button><Button onClick={exportPrompt}>Export .md</Button><Button onClick={() => window.open('https://chatgpt.com/', '_blank', 'noopener,noreferrer')}>Open ChatGPT</Button></div></Card><Card><CardHeader title="Import JSON workspace" hint="Syntax check only · not production schema validation" /><Textarea aria-label="Import JSON" value={json} onChange={e => { setJson(e.target.value); setResult('idle'); }} placeholder={'Paste the returned JSON here…'} /><div className="actions"><Button onClick={() => { setJson('{\n  "artifact_id": "demo_script_01",\n  "stage": "script"\n}'); setResult('idle'); }}>Use sample</Button><Button disabled={!json} onClick={() => { setJson(''); setResult('idle'); }}>Clear</Button><Button variant="primary" onClick={validate}>Validate syntax demo</Button></div>{result === 'valid' && <div className="info success">Valid JSON syntax · DEMO ONLY. No artifact was imported or accepted.</div>}{result === 'invalid' && <div className="info error" role="alert">Invalid JSON. Fix syntax before continuing.</div>}<Button disabled>Production import · Not connected</Button></Card></div>; }
